#define DIM 1024
int arr[DIM][DIM];

// Poor Spatial Locality (Stride DIM, accessing columns)
// High rate of cache misses
for (int j = 0; j < DIM; j++) {
    for (int i = 0; i < DIM; i++) {
        arr[i][j] = 0;
    }
}

// Good Spatial Locality (Stride 1, accessing rows)
// High cache line utilization
for (int i = 0; i < DIM; i++) {
    for (int j = 0; j < DIM; j++) {
        arr[i][j] = 0;
    }
}

#define N 512
#define TILE 32 // Block size optimized for L1/L2
float A[N][N], B[N][N], C[N][N];

// Cache Blocking (Tiling) for Matrix Multiplication
// Maximizes Temporal Locality of TILE x TILE blocks
for (int ii = 0; ii < N; ii += TILE) {
for (int jj = 0; jj < N; jj += TILE) {
for (int kk = 0; kk < N; kk += TILE) {
    // Core calculation restricted to current block
    for (int i = ii; i < ii + TILE; i++) {
        for (int j = jj; j < jj + TILE; j++) {
            for (int k = kk; k < kk + TILE; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}}}
